use crate::fact::{Fact, Span};
use klink_common::{Confidence, EdgeKind, FileId};

const MARKERS: &[&str] = &[
    "DO NOT EDIT",
    "@generated",
    "Code generated by",
    "Generated by the protocol buffer compiler",
    "AUTO-GENERATED",
];

/// Detect generated code headers and link back to the generator source as Heuristic.
pub fn detect_generator(file_id: FileId, content: &str) -> Option<Fact> {
    let head = &content[..content.len().min(2048)];
    let is_gen = MARKERS.iter().any(|m| head.contains(m));
    if !is_gen {
        return None;
    }

    // Look for a referenced `.proto`, `.openapi`, `.yaml`, or `.json` schema filename in the header
    for token in head.split_whitespace() {
        let clean = token.trim_matches(|c: char| !c.is_alphanumeric() && c != '.' && c != '_' && c != '-' && c != '/');
        if clean.ends_with(".proto")
            || clean.ends_with(".openapi.yaml")
            || clean.ends_with(".openapi.json")
            || clean.ends_with(".schema.json")
        {
            return Some(Fact {
                source: file_id,
                kind: EdgeKind::GeneratedFrom,
                raw_target: clean.to_string(),
                span: Span { start: 0, end: 0 },
                confidence: Confidence::Heuristic,
            });
        }
    }
    None
}
